R.result=()=>{const b=bmiOf(),w=rec()[0],t=(i,n,v,u)=>`<div class="card" style="padding:18px"><span class="chip-i" style="margin-bottom:14px">${ic(i)}</span><small class="mu">${n}</small><div style="font-size:28px;letter-spacing:-.04em;font-weight:500">${v}<small class="mu" style="font-size:14px;letter-spacing:0"> ${u}</small></div></div>`;
 return`<div class="body stack" style="padding-top:28px"><span class="pill g">${ic('check')} Assessment complete</span><h1>Your plan is ready, ${esc(S.user.split(' ')[0])}.</h1><p class="mu">Built for <b style="color:var(--tx)">${S.goal}</b> at ${S.level} level.</p><div class="card"><div class="row sp"><b>Body mass index</b><span class="pill">${bmiCat(b)}</span></div><div style="font-size:38px;letter-spacing:-.04em;font-weight:500;margin:10px 0 16px">${b.toFixed(1)}</div><div class="bmi"><i style="left:${bmiPos(b)}%"></i></div><div class="lg"><span>Under</span><span>Healthy</span><span>Over</span><span>Obese</span></div></div><div class="grid2">${t('flame','Daily calories',S.kcalGoal,'kcal')}${t('drop','Daily water',wGoal(),'glasses')}</div><div class="sec" style="margin:24px 0 0"><h3>Your first workout</h3></div><div class="ph"><div style="position:absolute;inset:0;background:url(${WIM(w)}) center/cover"></div><div class="ov"><div><span class="tag">${w.cat}</span><b>${w.name}</b><small>${mins(w)} min · ${w.kc} kcal</small></div></div></div><button class="btn btn-p" style="margin-top:20px" data-act="finishA">Start my journey ${ic('next')}</button></div>`};
/* ---------- 30-day strength challenge ---------- */
const CHP=(()=>{const wk=[2,3,4,0,2,3,0];return Array.from({length:30},(_,i)=>i==28?4:i==29?6:wk[i%7])})(),CHS=CHP.filter(Boolean).length,CHR=30-CHS,
CHW=[['Foundation','Learn the moves and build the habit.','1–7'],['Build','Add volume as your base gets stronger.','8–14'],['Push','Longer holds and tougher sets.','15–21'],['Peak','Your strongest week yet.','22–28'],['Finale','Two closing sessions to finish strong.','29–30']],
chWk=d=>Math.ceil(Math.min(Math.max(d,1),30)/7)-1,chW=d=>WORKOUTS.find(w=>w.id==CHP[d-1]);
let chSel=0;
const chDay=()=>{if(!S.ch)return 0;const a=new Date(S.ch.start),b=new Date();a.setHours(0,0,0,0);b.setHours(0,0,0,0);return Math.max(1,Math.round((b-a)/864e5)+1)};
const chCard=d=>{const cd=chDay(),w=chW(d),dn=S.ch.done.includes(d),st=!w?(d==cd?'Today':d<cd?'Rested':'Upcoming'):dn?'Completed':d==cd?'Today':d<cd?'Missed':'Upcoming';
 const sub=small=>`<small class="mu">Day ${d} · ${st}</small>`;
 if(!w)return`<div class="chc"><span class="chip-i rest">${ic('leaf')}</span><div class="grow">${sub()}<b>Rest day</b><small class="mu">Stretch, walk and drink water.</small></div></div>`;
 return`<div class="chc"><div class="t" style="background-image:url(${WIM(w)})"></div><div class="grow">${sub()}<b>${w.name}</b><small class="mu">${mins(w)} min · ${w.kc} kcal</small></div>${dn?`<span class="pill g">${ic('check')} Done</span>`:d==cd&&cd<=30?`<button class="btn btn-p sm" data-act="start" data-a="${w.id}">Start</button>`:`<button class="btn btn-g sm" data-go="detail" data-a="${w.id}">View</button>`}</div>`};
R.challenge=()=>{const j=S.ch,cd=chDay(),fin=j&&cd>30,cw=chWk(cd||1),
 hd=`<div class="dh ch-h" style="background-image:url(${IM('home/challenge')})"><div class="tp"><button class="ib glass" data-go="workouts" aria-label="Back">${ic('back')}</button></div><div class="ch-t"><span class="tag">${j?(fin?'Finished':`Week ${cw+1}: ${CHW[cw][0]}`):'New'}</span><h1>30-day strength challenge</h1></div></div>`;
 if(!j)return`${hd}<div class="dbody"><p>Four weeks of progressive strength training built from your workout library. Train on the scheduled days, rest on the others, and finish with a two-day finale.</p><div class="st3">${[['cal',30,'Days'],['dumb',CHS,'Sessions'],['leaf',CHR,'Rest days']].map(s=>`<div>${ic(s[0])}<b>${s[1]}</b><small>${s[2]}</small></div>`).join('')}</div><div class="sec"><h3>How it works</h3></div>${CHW.map((w,i)=>`<div class="chw"><span class="n">${i<4?i+1:ic('trophy')}</span><div><b>${w[0]}</b><small>Days ${w[2]}. ${w[1]}</small></div></div>`).join('')}<div class="sec"><h3>What you will train</h3></div><div class="muscles">${[2,3,4,6].map(id=>`<span class="pill">${WORKOUTS.find(w=>w.id==id).name}</span>`).join('')}</div></div><div class="cta"><button class="btn btn-p" data-act="chjoin">Join the challenge</button></div>`;
 const dn=j.done.length,sel=chSel||Math.min(cd,30);
 return`${hd}<div class="dbody"><section class="card"><div class="row sp"><div><small class="mu">${fin?'Challenge complete':'Your progress'}</small><div style="font-size:30px;letter-spacing:-.04em;font-weight:500">${fin?'30':cd}<small class="mu" style="font-size:15px;letter-spacing:0"> of 30 days</small></div></div><span class="pill ${dn?'g':''}">${dn} of ${CHS} sessions</span></div><div class="bar" style="margin:14px 0 16px"><i data-w="${Math.min(cd,30)/30*100}%"></i></div><div class="st3">${[['dumb',dn,'Sessions'],['flame',j.kc,'Kcal burned'],['target',Math.max(30-cd,0),'Days left']].map(s=>`<div>${ic(s[0])}<b>${s[1]}</b><small>${s[2]}</small></div>`).join('')}</div></section>
<div class="sec"><h3>Your 30 days</h3><span>Tap a day for details</span></div><div class="chg">${CHP.map((id,i)=>{const d=i+1,r=!id,x=j.done.includes(d),c=[x?'ok':'',r?'rs':'',d==cd?'td':'',d==sel?'sl':'',(!x&&!r&&d<cd)?'ms':'',d>cd?'fu':''].join(' ');return`<button class="${c}" data-act="chsel" data-a="${d}" aria-label="Day ${d}${r?', rest day':x?', completed':''}"><b>${d}</b>${x?ic('check'):r?ic('leaf'):''}</button>`}).join('')}</div>
<div class="chl"><span><i class="ok"></i>Done</span><span><i class="rs"></i>Rest</span><span><i class="ms"></i>Missed</span></div>
${fin?`<button class="btn btn-p" style="margin-top:22px" data-act="chjoin">Start again</button>`:''}<button class="btn btn-r" style="margin-top:${fin?10:22}px" data-act="chleave">Leave challenge</button></div><div class="cta"><div class="chs" id="chd">${chCard(sel)}</div></div>`};B.challenge=fill;
/* ---------- main ---------- */
const mt=(n,i,got,goal,c)=>`<div class="mt" style="--c:${c}"><small>${n}<br><span>Left</span></small><div class="rg" style="--p:${Math.min(got/goal,1)*100}">${ic(i)}</div><b>${Math.max(Math.round(goal-got),0)}<u>g</u></b></div>`;
