R.player=()=>{const s=P.steps[P.i],rest=s.rest,nx=P.steps[P.i+1];return`<div class="fs pl" style="background-image:url(${WIM(P.w)})"><div class="tp"><button class="ib glass" data-act="quit" aria-label="End workout">${ic('close')}</button><span class="tag">${P.w.name} · ${P.i+1}/${P.steps.length}</span></div><div class="pls"><div class="prog" style="margin-bottom:16px"><i style="width:${P.i/P.steps.length*100}%"></i></div><span class="pill ${rest?'':'g'}">${rest?'Rest · next: '+(nx?nx.name:'finish'):'Set '+s.set+' of '+s.of}</span><h2 style="margin:10px 0 0">${rest?'Take a breather':s.name}</h2>${ring(1-P.t/s.sec,210,'<span id="tm">'+P.t+'</span>','seconds',14)}<div class="st3" style="margin:8px 0 18px"><div>${ic('clock')}<b id="el">${P.el}</b><small>Seconds</small></div><div>${ic('flame')}<b id="kk">${Math.round(P.el*P.w.kc/P.total)}</b><small>Kcal</small></div><div>${ic('target')}<b>${P.i+1}/${P.steps.length}</b><small>Steps</small></div></div><div class="row"><button class="ib dk" data-act="skipstep" style="width:58px;height:58px" aria-label="Skip step">${ic('skip')}</button><button class="btn btn-k" data-act="pp" id="pp">${ic('pause')} Pause</button></div></div></div>`};
B.player=()=>fill();
function startTimer(){clearInterval(tm);tm=setInterval(()=>{if(!P.run)return;P.t--;P.el++;if(P.t<=0)return next();if(P.t<=3)cue(1);const f=$('.ring .fg'),s=P.steps[P.i];$('#tm').textContent=P.t;$('#el').textContent=P.el;$('#kk').textContent=Math.round(P.el*P.w.kc/P.total);f.style.strokeDashoffset=f.dataset.c*(P.t/s.sec)},1000)}
