function finish(){clearInterval(tm);const k=Math.max(5,Math.round(P.el*P.w.kc/P.total)),m=Math.max(1,Math.round(P.el/60));S.hist.push({t:Date.now(),min:m,kc:k,name:P.w.name});let ch=0;if(S.ch){const cd=chDay();if(cd<=30&&CHP[cd-1]==P.w.id&&!S.ch.done.includes(cd)){S.ch.done.push(cd);S.ch.kc+=k;ch=cd}}notify('dumb','Workout complete',`${P.w.name} · ${m} min · ${k} kcal burned`);chkWk();save();go('done',{k,m,n:P.w.name,ch})}
